CREATE TABLE IF NOT EXISTS disaster_recovery_assessments (id BIGINT AUTO_INCREMENT PRIMARY KEY, application_name VARCHAR(255) NOT NULL, primary_cloud VARCHAR(100) NOT NULL, recovery_cloud VARCHAR(100) NOT NULL, readiness_score INT NOT NULL, rto_minutes INT NOT NULL, rpo_minutes INT NOT NULL, recovery_probability DOUBLE NOT NULL, risk_level VARCHAR(30) NOT NULL, backup_health VARCHAR(30) NOT NULL, failover_readiness VARCHAR(30) NOT NULL, assessed_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS recovery_simulations (id BIGINT AUTO_INCREMENT PRIMARY KEY, application_name VARCHAR(255) NOT NULL, scenario VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, estimated_recovery_minutes INT NOT NULL, achieved_rto_minutes INT NOT NULL, data_loss_minutes INT NOT NULL, recovery_plan VARCHAR(2000), executed_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS business_impact_analyses (id BIGINT AUTO_INCREMENT PRIMARY KEY, application_name VARCHAR(255) NOT NULL, incident_type VARCHAR(100) NOT NULL, affected_services INT NOT NULL, estimated_users_affected BIGINT NOT NULL, estimated_financial_impact DOUBLE NOT NULL, severity VARCHAR(30) NOT NULL, continuity_recommendation VARCHAR(1500), analyzed_at DATETIME(6) NOT NULL);
